-- HYDROLAND canonical HR lifecycle migration.
-- Production foundation stores identity and organization identifiers as PostgreSQL UUID. Keep HR identifiers and every FK to those canonical tables UUID-compatible.
CREATE TYPE "OrgUnitType" AS ENUM ('HQ','REGION','CENTER','DEPARTMENT','UNIT','TEAM');
CREATE TYPE "EmploymentStatus" AS ENUM ('DRAFT','PENDING_APPROVAL','ACTIVE','ON_LEAVE','SUSPENDED','TERMINATED','OFFBOARDED');
CREATE TYPE "WorkerClass" AS ENUM ('EMPLOYEE','TEMPORARY_WORKER','INDEPENDENT_PROFESSIONAL','CONTRACTOR','CENTER_AFFILIATED','TRIP_ONLY');
CREATE TYPE "EmploymentMovementType" AS ENUM ('APPOINTMENT','TRANSFER','TEMPORARY_ASSIGNMENT','PROMOTION','DEMOTION','SUSPENSION','RETURN_TO_ROLE','TERMINATION');
CREATE TYPE "HrRequestStatus" AS ENUM ('DRAFT','SUBMITTED','HR_REVIEW','APPROVAL_REQUIRED','APPROVED','REJECTED','CANCELLED','EFFECTIVE','CLOSED');

CREATE TABLE "OrgUnit" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"organizationId" UUID NOT NULL,"parentId" UUID,"type" "OrgUnitType" NOT NULL,"code" TEXT NOT NULL,"nameAr" TEXT NOT NULL,"nameEn" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OrgUnit_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "OrgUnit_organizationId_code_key" ON "OrgUnit"("organizationId","code");
CREATE INDEX "OrgUnit_organizationId_parentId_type_idx" ON "OrgUnit"("organizationId","parentId","type");
CREATE TABLE "Position" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"orgUnitId" UUID NOT NULL,"code" TEXT NOT NULL,"titleAr" TEXT NOT NULL,"titleEn" TEXT,"active" BOOLEAN NOT NULL DEFAULT true,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Position_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Position_orgUnitId_code_key" ON "Position"("orgUnitId","code");
CREATE TABLE "Employment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"accountId" UUID NOT NULL,"organizationId" UUID NOT NULL,"orgUnitId" UUID NOT NULL,"positionId" UUID,"managerEmploymentId" UUID,"workerClass" "WorkerClass" NOT NULL,"status" "EmploymentStatus" NOT NULL DEFAULT 'DRAFT',"startsAt" TIMESTAMP(3),"endsAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "Employment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "Employment_accountId_status_idx" ON "Employment"("accountId","status");
CREATE INDEX "Employment_organizationId_orgUnitId_status_idx" ON "Employment"("organizationId","orgUnitId","status");
CREATE TABLE "EmploymentContract" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"contractType" TEXT NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"documentId" UUID,"status" TEXT NOT NULL DEFAULT 'DRAFT',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmploymentContract_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "EmploymentContract_employmentId_version_key" ON "EmploymentContract"("employmentId","version");
CREATE TABLE "EmploymentMovement" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"type" "EmploymentMovementType" NOT NULL,"status" "HrRequestStatus" NOT NULL DEFAULT 'DRAFT',"fromOrgUnitId" UUID,"toOrgUnitId" UUID,"fromPositionId" UUID,"toPositionId" UUID,"requestedByAccountId" UUID NOT NULL,"reviewedByAccountId" UUID,"approvedByAccountId" UUID,"effectiveAt" TIMESTAMP(3),"reason" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmploymentMovement_pkey" PRIMARY KEY ("id"));
CREATE INDEX "EmploymentMovement_employmentId_status_idx" ON "EmploymentMovement"("employmentId","status");
CREATE TABLE "LeaveRequest" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"type" TEXT NOT NULL,"status" "HrRequestStatus" NOT NULL DEFAULT 'DRAFT',"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"requestedByAccountId" UUID NOT NULL,"approvedByAccountId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "LeaveRequest_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AttendanceEntry" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"workDate" DATE NOT NULL,"clockInAt" TIMESTAMP(3),"clockOutAt" TIMESTAMP(3),"status" TEXT NOT NULL DEFAULT 'PENDING',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "AttendanceEntry_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "AttendanceEntry_employmentId_workDate_key" ON "AttendanceEntry"("employmentId","workDate");
CREATE TABLE "ShiftAssignment" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"startsAt" TIMESTAMP(3) NOT NULL,"endsAt" TIMESTAMP(3) NOT NULL,"shiftCode" TEXT,"status" TEXT NOT NULL DEFAULT 'SCHEDULED',"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "ShiftAssignment_pkey" PRIMARY KEY ("id"));
CREATE INDEX "ShiftAssignment_employmentId_startsAt_idx" ON "ShiftAssignment"("employmentId","startsAt");
CREATE INDEX "ShiftAssignment_status_idx" ON "ShiftAssignment"("status");
CREATE TABLE "CompensationTerm" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"effectiveFrom" TIMESTAMP(3) NOT NULL,"effectiveTo" TIMESTAMP(3),"baseAmountMinor" INTEGER,"currency" TEXT NOT NULL DEFAULT 'SAR',"allowances" JSONB,"benefits" JSONB,"status" "HrRequestStatus" NOT NULL DEFAULT 'DRAFT',"approvedByAccountId" UUID,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "CompensationTerm_pkey" PRIMARY KEY ("id"));
CREATE INDEX "CompensationTerm_employmentId_effectiveFrom_idx" ON "CompensationTerm"("employmentId","effectiveFrom");
CREATE INDEX "CompensationTerm_status_idx" ON "CompensationTerm"("status");
CREATE TABLE "PerformanceCycle" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"periodStart" DATE NOT NULL,"periodEnd" DATE NOT NULL,"status" TEXT NOT NULL DEFAULT 'DRAFT',"goals" JSONB,"managerAssessment" JSONB,"hrReview" JSONB,"developmentPlan" JSONB,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "PerformanceCycle_pkey" PRIMARY KEY ("id"));
CREATE TABLE "EmployeeRelationsCase" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"caseType" TEXT NOT NULL,"status" "HrRequestStatus" NOT NULL DEFAULT 'DRAFT',"openedByAccountId" UUID NOT NULL,"reviewedByAccountId" UUID,"approvedByAccountId" UUID,"summary" TEXT,"decision" TEXT,"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "EmployeeRelationsCase_pkey" PRIMARY KEY ("id"));
CREATE TABLE "OffboardingCase" ("id" UUID NOT NULL DEFAULT gen_random_uuid(),"employmentId" UUID NOT NULL,"status" "HrRequestStatus" NOT NULL DEFAULT 'DRAFT',"reason" TEXT,"lastWorkingAt" TIMESTAMP(3),"clearance" JSONB,"iamRevokedAt" TIMESTAMP(3),"closedAt" TIMESTAMP(3),"createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "OffboardingCase_pkey" PRIMARY KEY ("id"));

ALTER TABLE "OrgUnit" ADD CONSTRAINT "OrgUnit_organizationId_fkey" FOREIGN KEY ("organizationId") REFERENCES "Organization"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
ALTER TABLE "OrgUnit" ADD CONSTRAINT "OrgUnit_parentId_fkey" FOREIGN KEY ("parentId") REFERENCES "OrgUnit"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
