ALTER TABLE "EmploymentMovement" ADD CONSTRAINT "EmploymentMovement_toPositionId_fkey" FOREIGN KEY ("toPositionId") REFERENCES "Position"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
