ALTER TABLE "EmploymentMovement" ADD CONSTRAINT "EmploymentMovement_reviewedByAccountId_fkey" FOREIGN KEY ("reviewedByAccountId") REFERENCES "Account"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
