ALTER TABLE "LeaveRequest" ADD CONSTRAINT "LeaveRequest_requestedByAccountId_fkey" FOREIGN KEY ("requestedByAccountId") REFERENCES "Account"("id") ON DELETE RESTRICT ON UPDATE CASCADE;
